package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod = 1000000007

var dp [55][55][205]int64
var c [55][55]int64
var n, lim, A, B, i, j, k, ii, jj int

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a < b {
		return b
	}
	return a
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	fmt.Fscan(reader, &n, &lim)
	for i = 0; i < n; i++ {
		var fk int
		fmt.Fscan(reader, &fk)
		if fk == 50 {
			A++
		} else {
			B++
		}
	}
	dp[A][B][0] = 1
	c[0][0] = 1
	for i = 1; i <= 50; i++ {
		for j = 0; j <= i; j++ {
			c[i][j] = c[i-1][j-1] + c[i-1][j]
		}
	}

	for k = 1; k <= 4*n; k++ {
		for i = A; i >= 0; i-- {
			for j = B; j >= 0; j-- {
				s := k % 2
				dp[i][j][k] = 0
				if s != 0 {
					for ii = i; ii <= A; ii++ {
						f := lim - (ii-i)*50
						if f >= 0 {
							f /= 100
							f += j
							f = min(f, B)
							for jj = j; jj <= f; jj++ {
								if i != ii || j != jj {
									dp[i][j][k] += (dp[ii][jj][k-1] * c[ii][ii-i] * c[jj][jj-j]) % mod
									dp[i][j][k] %= mod
								}
							}
						}
					}
				} else {
					for ii = 0; ii <= i; ii++ {
						f := lim - (i-ii)*50
						if f >= 0 {
							f /= 100
							f = max(j-f, 0)
							for jj = f; jj <= j; jj++ {
								if i != ii || j != jj {
									dp[i][j][k] += (dp[ii][jj][k-1] * c[A-ii][i-ii] * c[B-jj][j-jj]) % mod
									dp[i][j][k] %= mod
								}
							}
						}
					}
				}
				if dp[0][0][k] != 0 {
					fmt.Fprintln(writer, k)
					fmt.Fprintln(writer, dp[0][0][k])
					return
				}
			}
		}
	}
	fmt.Fprintln(writer, "-1")
	fmt.Fprintln(writer, "0")
}
